arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "channel=C_LAUNCH&limit=500" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d.get('error')); sys.exit(1)
for m in d['messages']:
    if m.get('subtype'): continue
    react={}
    for r in m.get('reactions',[]):
        react[r['name']]=r.get('users',[])
    if 'thumbsup' in react:
        print(m['ts'],'|',m.get('user'),'|',m.get('text','')[:150])
        print('   thumbsup by:', react['thumbsup'])
"

